	int i = 0;
	for (std::multimap<std::string,HeaderField*>::iterator iter = range.first; iter != range.second; ++iter)
	{
		if (i == index)
		{
			fieldToRemove = iter->second;
			break;
		}

		i++;
	}

	if (fieldToRemove != nullptr)
