   249	
   250		return newFieldToAdd;
   251	}
   252	
   253	bool TextBasedProtocolMessage::removeField(std::string fieldName, int index)
   254	{
   255		std::transform(fieldName.begin(), fieldName.end(), fieldName.begin(), ::tolower);
   256	
   257		HeaderField* fieldToRemove = nullptr;
   258	
   259		std::pair <std::multimap<std::string,HeaderField*>::iterator, std::multimap<std::string,HeaderField*>::iterator> range;
   260		range = m_FieldNameToFieldMap.equal_range(fieldName);
   261		int i = 0;
   262		for (std::multimap<std::string,HeaderField*>::iterator iter = range.first; iter != range.second; ++iter)
   263		{
   264			if (i == index)
   265			{
   266				fieldToRemove = iter->second;
   267				break;
   268			}
   269	
   270			i++;
   271		}
   272	
   273		if (fieldToRemove != nullptr)
   274			return removeField(fieldToRemove);
   275		else
   276		{
   277			PCPP_LOG_ERROR("Cannot find field '" << fieldName << "'");
   278			return false;
   279		}
   280	}
   281	
   282	bool TextBasedProtocolMessage::removeField(HeaderField* fieldToRemove)
   283	{
   284		if (fieldToRemove == nullptr)
   285			return true;
   286	
   287		if (fieldToRemove->m_TextBasedProtocolMessage != this)
   288		{
   289			PCPP_LOG_ERROR("Field isn't associated with this message");
   290			return false;
   291		}
   292	
   293		std::string fieldName = fieldToRemove->getFieldName();
   294	
   295		// shorten layer and delete this field
   296		if (!shortenLayer(fieldToRemove->m_NameOffsetInMessage, fieldToRemove->getFieldSize()))
   297		{
   298			PCPP_LOG_ERROR("Cannot shorten layer");
   299			return false;
   300		}
   301	
   302		// update offsets of all fields after this field
   303		HeaderField* curField = fieldToRemove->getNextField();
   304		shiftFieldsOffset(curField, 0-fieldToRemove->getFieldSize());
   305	//	while (curField != NULL)
   306	//	{
   307	//		curField->m_NameOffsetInMessage -= fieldToRemove->getFieldSize();
   308	//		if (curField->m_ValueOffsetInMessage != -1)
   309	//			curField->m_ValueOffsetInMessage -= fieldToRemove->getFieldSize();
   310	//
   311	//		curField = curField->getNextField();
   312	//	}
   313	
   314		// update fields link list
   315		if (fieldToRemove == m_FieldList)
   316			m_FieldList = m_FieldList->getNextField();
   317		else
   318		{
   319			curField = m_FieldList;
   320			while (curField->getNextField() != fieldToRemove)
   321				curField = curField->getNextField();
   322	
   323			curField->setNextField(fieldToRemove->getNextField());
   324		}
   325	
   326		// re-calculate m_LastField if needed
   327		if (fieldToRemove == m_LastField)
   328		{
   329			if (m_FieldList == nullptr)
   330				m_LastField = nullptr;
   331			else
   332			{
   333				curField = m_FieldList;
   334				while (curField->getNextField() != nullptr)
   335					curField = curField->getNextField();
   336				m_LastField = curField;
   337			}
   338		}
   339	
   340		// remove the hash entry for this field
   341		std::transform(fieldName.begin(), fieldName.end(), fieldName.begin(), ::tolower);
   342		std::pair <std::multimap<std::string,HeaderField*>::iterator, std::multimap<std::string,HeaderField*>::iterator> range;
   343		range = m_FieldNameToFieldMap.equal_range(fieldName);
   344		for (std::multimap<std::string,HeaderField*>::iterator iter = range.first; iter != range.second; ++iter)
   345		{
   346			if (iter->second == fieldToRemove)
   347			{
   348				m_FieldNameToFieldMap.erase(iter);
   349				break;
   350			}
   351		}
   352	
   353		// finally - delete this field
   354		delete fieldToRemove;
   355	
   356		return true;
   357	}
   358	
   359	bool TextBasedProtocolMessage::isHeaderComplete() const
   360	{
   361		if (m_LastField == nullptr)
   362			return false;
   363	
   364		return (m_LastField->getFieldName() == PCPP_END_OF_TEXT_BASED_PROTOCOL_HEADER);
   365	}
