   367	void TextBasedProtocolMessage::shiftFieldsOffset(HeaderField* fromField, int numOfBytesToShift)
   368	{
   369		while (fromField != nullptr)
   370		{
   371			fromField->m_NameOffsetInMessage += numOfBytesToShift;
   372			if (fromField->m_ValueOffsetInMessage != -1)
   373				fromField->m_ValueOffsetInMessage += numOfBytesToShift;
   374			fromField = fromField->getNextField();
   375		}
