   434	// -------- Class HeaderField -----------------
   435	
   436	
   437	HeaderField::HeaderField(TextBasedProtocolMessage* TextBasedProtocolMessage, int offsetInMessage, char nameValueSeparator, bool spacesAllowedBetweenNameAndValue) :
   438			m_NewFieldData(nullptr), m_TextBasedProtocolMessage(TextBasedProtocolMessage), m_NameOffsetInMessage(offsetInMessage), m_NextField(nullptr),
   439			m_NameValueSeparator(nameValueSeparator), m_SpacesAllowedBetweenNameAndValue(spacesAllowedBetweenNameAndValue)
   440	{
   441		char* fieldData = (char*)(m_TextBasedProtocolMessage->m_Data + m_NameOffsetInMessage);
   442		char* fieldEndPtr = (char*)memchr(fieldData, '\n', m_TextBasedProtocolMessage->m_DataLen - (size_t)m_NameOffsetInMessage);
   443		if (fieldEndPtr == nullptr)
   444			m_FieldSize = tbp_my_own_strnlen(fieldData, m_TextBasedProtocolMessage->m_DataLen - (size_t)m_NameOffsetInMessage);
   445		else
   446			m_FieldSize = fieldEndPtr - fieldData + 1;
   447	
   448		if (m_FieldSize == 0 || (*fieldData) == '\r' || (*fieldData) == '\n')
   449		{
   450			m_FieldNameSize = -1;
   451			m_ValueOffsetInMessage = -1;
   452			m_FieldValueSize = -1;
   453			m_FieldNameSize = -1;
   454			m_IsEndOfHeaderField = true;
   455			return;
   456		}
   457		else
   458			m_IsEndOfHeaderField = false;
   459	
   460		char* fieldValuePtr = (char*)memchr(fieldData, nameValueSeparator, m_TextBasedProtocolMessage->m_DataLen - (size_t)m_NameOffsetInMessage);
   461		// could not find the position of the separator, meaning field value position is unknown
   462		if (fieldValuePtr == nullptr || (fieldEndPtr != nullptr && fieldValuePtr >= fieldEndPtr))
   463		{
   464			m_ValueOffsetInMessage = -1;
   465			m_FieldValueSize = -1;
   466			m_FieldNameSize = m_FieldSize;
   467		}
   468		else
   469		{
   470			m_FieldNameSize = fieldValuePtr - fieldData;
   471			// Header field looks like this: <field_name>[separator]<zero or more spaces><field_Value>
   472			// So fieldValuePtr give us the position of the separator. Value offset is the first non-space byte forward
   473			fieldValuePtr++;
   474	
   475			// reached the end of the packet and value start offset wasn't found
   476			if ((size_t)(fieldValuePtr - (char*)(m_TextBasedProtocolMessage->m_Data)) >= m_TextBasedProtocolMessage->getDataLen())
   477			{
   478				m_ValueOffsetInMessage = -1;
   479				m_FieldValueSize = -1;
   480				return;
   481			}
   482	
   483			if (spacesAllowedBetweenNameAndValue)
   484			{
   485				// advance fieldValuePtr 1 byte forward while didn't get to end of packet and fieldValuePtr points to a space char
   486				while ((size_t)(fieldValuePtr - (char*)m_TextBasedProtocolMessage->m_Data) < m_TextBasedProtocolMessage->getDataLen() && (*fieldValuePtr) == ' ')
   487				{
   488					fieldValuePtr++;
   489				}
   490			}
   491	
   492			// reached the end of the packet and value start offset wasn't found
   493			if ((size_t)(fieldValuePtr - (char*)(m_TextBasedProtocolMessage->m_Data)) >= m_TextBasedProtocolMessage->getDataLen())
   494			{
   495				m_ValueOffsetInMessage = -1;
   496				m_FieldValueSize = -1;
   497			}
   498			else
   499			{
   500				m_ValueOffsetInMessage = fieldValuePtr - (char*)m_TextBasedProtocolMessage->m_Data;
   501				// couldn't find the end of the field, so assuming the field value length is from m_ValueOffsetInMessage until the end of the packet
   502				if (fieldEndPtr == nullptr)
   503					m_FieldValueSize = (char*)(m_TextBasedProtocolMessage->m_Data + m_TextBasedProtocolMessage->getDataLen()) - fieldValuePtr;
   504				else
   505				{
   506					m_FieldValueSize = fieldEndPtr - fieldValuePtr;
   507					// if field ends with \r\n, decrease the value length by 1
   508					if ((*(--fieldEndPtr)) == '\r')
   509						m_FieldValueSize--;
   510				}
   511			}
   512		}
   513	}
   514	
   515	HeaderField::HeaderField(const std::string& name, const std::string& value, char nameValueSeparator, bool spacesAllowedBetweenNameAndValue)
   516	{
   517		m_NameValueSeparator = nameValueSeparator;
   518		m_SpacesAllowedBetweenNameAndValue = spacesAllowedBetweenNameAndValue;
   519		initNewField(std::move(name), std::move(value));
   520	}
   521	
   522	void HeaderField::initNewField(const std::string& name, const std::string& value)
   523	{
   524		m_TextBasedProtocolMessage = nullptr;
   525		m_NameOffsetInMessage = 0;
   526		m_NextField = nullptr;
   527	
   528		// first building the name-value separator
   529		std::string nameValueSeparation(1, m_NameValueSeparator);
   530		if (m_SpacesAllowedBetweenNameAndValue)
   531			nameValueSeparation += " ";
   532	
   533		// Field size is: name_length + separator_len + value_length + '\r\n'
   534		if (name != PCPP_END_OF_TEXT_BASED_PROTOCOL_HEADER)
   535			m_FieldSize = name.length() + nameValueSeparation.length() + value.length() + 2;
   536		else
   537		// Field is \r\n (2B)
   538			m_FieldSize = 2;
   539	
   540		m_NewFieldData = new uint8_t[m_FieldSize];
   541		std::string fieldData;
   542	
   543		if (name != PCPP_END_OF_TEXT_BASED_PROTOCOL_HEADER)
   544			fieldData = name + nameValueSeparation + value + "\r\n";
   545		else
   546			fieldData = "\r\n";
   547	
   548		// copy field data to m_NewFieldData
   549		memcpy(m_NewFieldData, fieldData.c_str(), m_FieldSize);
   550	
   551		// calculate value offset
   552		if (name != PCPP_END_OF_TEXT_BASED_PROTOCOL_HEADER)
   553			m_ValueOffsetInMessage = name.length() + nameValueSeparation.length();
   554		else
   555			m_ValueOffsetInMessage = 0;
   556		m_FieldNameSize = name.length();
   557		m_FieldValueSize = value.length();
   558	
   559		if (name != PCPP_END_OF_TEXT_BASED_PROTOCOL_HEADER)
   560			m_IsEndOfHeaderField = false;
   561		else
   562			m_IsEndOfHeaderField = true;
   563	}
   564	
   565	HeaderField::~HeaderField()
   566	{
   567		if (m_NewFieldData != nullptr)
   568			delete [] m_NewFieldData;
   569	}
   570	
   571	HeaderField::HeaderField(const HeaderField& other) : m_NameValueSeparator('\0'), m_SpacesAllowedBetweenNameAndValue(false)
   572	{
   573		m_NameValueSeparator = other.m_NameValueSeparator;
   574		m_SpacesAllowedBetweenNameAndValue = other.m_SpacesAllowedBetweenNameAndValue;
   575		initNewField(other.getFieldName(), other.getFieldValue());
   576	}
   577	
   578	HeaderField& HeaderField::operator=(const HeaderField& other)
   579	{
   580		m_NameValueSeparator = other.m_NameValueSeparator;
   581		m_SpacesAllowedBetweenNameAndValue = other.m_SpacesAllowedBetweenNameAndValue;
   582		if (m_NewFieldData != nullptr)
   583			delete [] m_NewFieldData;
   584		initNewField(other.getFieldName(), other.getFieldValue());
   585	
   586		return (*this);
   587	}
   588	
   589	char* HeaderField::getData() const
   590	{
   591		if (m_TextBasedProtocolMessage == nullptr)
   592			return (char*)m_NewFieldData;
   593		else
   594			return (char*)(m_TextBasedProtocolMessage->m_Data);
   595	}
   596	
   597	void HeaderField::setNextField(HeaderField* nextField)
   598	{
   599		m_NextField = nextField;
   600	}
   601	
   602	HeaderField* HeaderField::getNextField() const
   603	{
   604		return m_NextField;
   605	}
   606	
   607	std::string HeaderField::getFieldName() const
   608	{
   609		std::string result;
   610	
   611		if (m_FieldNameSize != (size_t)-1)
   612			result.assign((const char*)(((HeaderField*)this)->getData() + m_NameOffsetInMessage), m_FieldNameSize);
   613	
   614		return result;
   615	}
   616	
   617	std::string HeaderField::getFieldValue() const
   618	{
   619		std::string result;
   620		if (m_ValueOffsetInMessage != -1)
   621			result.assign((const char*)(((HeaderField*)this)->getData() + m_ValueOffsetInMessage), m_FieldValueSize);
   622		return result;
   623	}
   624	
   625	bool HeaderField::setFieldValue(const std::string& newValue)
   626	{
   627		// Field isn't linked with any message yet
   628		if (m_TextBasedProtocolMessage == nullptr)
   629		{
   630			std::string name = getFieldName();
   631			delete [] m_NewFieldData;
   632			initNewField(name, newValue);
   633			return true;
   634		}
   635	
   636		std::string curValue = getFieldValue();
   637		int lengthDifference = newValue.length() - curValue.length();
   638		// new value is longer than current value
   639		if (lengthDifference > 0)
   640		{
   641			if (!m_TextBasedProtocolMessage->extendLayer(m_ValueOffsetInMessage, lengthDifference))
   642			{
   643				PCPP_LOG_ERROR("Could not extend layer");
   644				return false;
   645			}
   646		}
   647		// new value is shorter than current value
   648		else if (lengthDifference < 0)
   649		{
   650			if (!m_TextBasedProtocolMessage->shortenLayer(m_ValueOffsetInMessage, 0 - lengthDifference))
   651			{
   652				PCPP_LOG_ERROR("Could not shorten layer");
   653				return false;
   654			}
   655		}
   656	
   657		if (lengthDifference != 0)
   658			m_TextBasedProtocolMessage->shiftFieldsOffset(getNextField(), lengthDifference);
   659	
   660		// update sizes
   661		m_FieldValueSize += lengthDifference;
   662		m_FieldSize += lengthDifference;
   663	
   664		// write new value to field data
   665		memcpy(getData() + m_ValueOffsetInMessage, newValue.c_str(), newValue.length());
   666	
   667		return true;
   668	}
   669	
   670	void HeaderField::attachToTextBasedProtocolMessage(TextBasedProtocolMessage* message, int fieldOffsetInMessage)
   671	{
   672		if (m_TextBasedProtocolMessage != nullptr && m_TextBasedProtocolMessage != message)
   673		{
   674			PCPP_LOG_ERROR("Header field already associated with another message");
   675			return;
   676		}
   677	
   678		if (m_NewFieldData == nullptr)
   679		{
   680			PCPP_LOG_ERROR("Header field doesn't have new field data");
   681			return;
   682		}
   683	
   684		delete [] m_NewFieldData;
   685		m_NewFieldData = nullptr;
   686		m_TextBasedProtocolMessage = message;
   687	
   688		int valueAndNameDifference = m_ValueOffsetInMessage - m_NameOffsetInMessage;
   689		m_NameOffsetInMessage = fieldOffsetInMessage;
   690		m_ValueOffsetInMessage = m_NameOffsetInMessage + valueAndNameDifference;
   691	}
